{
  "name": "abpilot",
  "version": "2.0.2",
  "description": "ABPilot CLI: a local UI for the gateway, OpenCode AI chat, and skill apps",
  "type": "module",
  "bin": {
    "abpilot": "bin/abpilot.js"
  },
  "files": [
    "bin",
    "lib",
    "ui/dist",
    "README.md"
  ],
  "scripts": {
    "ui": "node bin/abpilot.js ui",
    "gateway:status": "node bin/abpilot.js gateway status",
    "build:ui": "npm --prefix ui install && npm --prefix ui run build",
    "prepack": "npm run build:ui",
    "test": "node --test test/*.test.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "abpilot",
    "iroh",
    "gateway",
    "opencode",
    "skills"
  ],
  "license": "UNLICENSED",
  "dependencies": {
    "@opencode/cli": "2.0.27",
    "express": "^5.2.1",
    "ws": "^8.21.3"
  }
}
